mapper.select:
SELECT sd.product_name AS productName, so.order_no AS orderNo, sd.price AS price, sd.quantity AS quantity, sd.amount AS amount, so.member_name AS memberName, so.create_time AS createTime FROM sale_detail sd INNER JOIN sale_order so ON sd.order_id = so.id WHERE so.is_deleted = 0
AND sd.product_name LIKE CONCAT('%', #{productName}, '%')
AND so.create_time >= #{startTime}
AND so.create_time <= #{endTime}
ORDER BY so.create_time DESC

SELECT sd.product_name AS productName, MAX(sd.price) AS price, SUM(sd.quantity) AS totalQuantity, SUM(sd.amount) AS totalAmount FROM sale_detail sd INNER JOIN sale_order so ON sd.order_id = so.id WHERE so.is_deleted = 0 AND so.status = 1
AND sd.product_name LIKE CONCAT('%', #{productName}, '%')
AND so.create_time >= #{startTime}
AND so.create_time <= #{endTime}
GROUP BY sd.product_id, sd.product_name ORDER BY totalAmount DESC
